import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Feed } from '../types'

const PANE = 'tool-snake'
const EMPTY: Feed = { working: false, turn: 0, foods: [] }

const feed = atom({ plugin: 'tool-snake', key: 'feed' } as const, EMPTY)
const best = atom({ plugin: 'tool-snake', key: 'best' } as const, 0)

type Final = { type: 'final'; eaten: number; total: number; score: number }

const isFinal = (d: unknown): d is Final =>
  typeof d === 'object' && d !== null && (d as { type?: unknown }).type === 'final'

export const finalLine = (f: Final): string =>
  f.total === 0
    ? 'Claude is done.'
    : `Claude is done. You ate ${f.eaten} of its ${f.total} tool call${f.total === 1 ? '' : 's'}.`

export const register: Register = on => {
  let counter = 0

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'snake',
      description: 'tool-snake: open the game pane',
    })
    return next(e)
  })

  on('command.run', { command: 'snake' }, async $ => {
    await $.ui.open({ id: PANE, title: 'tool snake' })
    return { text: 'tool-snake: click the game to play, Esc to give the keys back.' }
  })

  on('prompt.submit', async ($, e, next) => {
    await update($, feed, f => ({ working: true, turn: f.turn + 1, foods: [] }))
    // A prompt the person entered counts as asking, so the pane opens at any width.
    void $.ui.open({ id: PANE, title: 'tool snake' })
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    if (e.agentId === undefined) {
      counter += 1
      const id = e.tool_use_id ?? `t${counter}`
      await update($, feed, f => ({ ...f, foods: [...f.foods, { id, tool: e.tool }].slice(-60) }))
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      await update($, feed, f => ({ ...f, working: false }))
    }
    return next(e)
  })

  on('ui.message', async ($, e, next) => {
    if (e.requestId === PANE && isFinal(e.data)) {
      const f = e.data
      const top = await read($, best)
      const isBest = f.score > top
      if (isBest) await update($, best, () => f.score)
      $.ui.toast(`tool-snake: ${finalLine(f)}${isBest ? ' New best!' : ''}`)
      $.audio.speak(finalLine(f)).catch(() => undefined)
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const els = $.ui.resolve(e)
    const { Box, Text } = els
    const Client = 'Client' in els ? els.Client : undefined
    const f = await read($, feed)
    const top = await read($, best)

    return (
      <Box flexDirection="column">
        <Text dimColor>every tool call Claude makes drops food · best {top}</Text>
        {Client ? (
          <Client key="game" module="./game.tsx" props={f} width={46} height={17} />
        ) : (
          <Text dimColor>The game needs the terminal or desktop app.</Text>
        )}
      </Box>
    )
  })
}

