import type { ClientKeyEvent, ClientSurface, RenderElement } from 'claude-code'

import type { Feed } from '../types'

// Board in cells; each cell is drawn 2 characters wide so it looks square.
export const W = 22
export const H = 12

type P = { x: number; y: number }
type Dot = P & { id: string; tool: string }
type Dir = 'up' | 'down' | 'left' | 'right'

type S = {
  snake: P[]
  dir: Dir
  next: Dir
  dots: Dot[]
  seen: string[]
  score: number
  eaten: number
  total: number
  turn: number
  alive: boolean
  wasWorking: boolean
  seed: number
}

// The latest props per instance, read by the tick (closures from the first call hold old props).
const latest = new WeakMap<object, Feed>()

const COLORS: Record<string, string> = {
  Bash: '#facc15',
  Edit: '#e879f9',
  MultiEdit: '#e879f9',
  Write: '#fb923c',
  Read: '#22d3ee',
  Grep: '#60a5fa',
  Glob: '#60a5fa',
}
const letter = (tool: string): string => (tool.replace(/^mcp__/, '')[0] ?? '?').toUpperCase()
const colorOf = (tool: string): string => COLORS[tool] ?? '#e5e7eb'

const OPPOSITE: Record<Dir, Dir> = { up: 'down', down: 'up', left: 'right', right: 'left' }
const KEYS: Record<string, Dir> = {
  up: 'up', down: 'down', left: 'left', right: 'right',
  w: 'up', s: 'down', a: 'left', d: 'right',
}

// Small deterministic random so a restart doesn't need Math.random.
const rand = (s: S, n: number): number => {
  s.seed = (s.seed * 1103515245 + 12345) & 0x7fffffff
  return s.seed % n
}

export const fresh = (turn: number, seed = 7): S => ({
  snake: [{ x: 10, y: 8 }, { x: 9, y: 8 }, { x: 8, y: 8 }],
  dir: 'right',
  next: 'right',
  dots: [],
  seen: [],
  score: 0,
  eaten: 0,
  total: 0,
  turn,
  alive: true,
  wasWorking: false,
  seed,
})

const occupied = (s: S, p: P): boolean =>
  s.snake.some(c => c.x === p.x && c.y === p.y) || s.dots.some(d => d.x === p.x && d.y === p.y)

// One step of the world: new food from Claude's tool calls, then the snake moves.
export const step = (prev: S, feed: Feed): { s: S; final?: { eaten: number; total: number; score: number } } => {
  const s: S = { ...prev, snake: [...prev.snake], dots: [...prev.dots], seen: [...prev.seen] }
  let final: { eaten: number; total: number; score: number } | undefined

  if (feed.turn !== s.turn) {
    s.turn = feed.turn
    s.eaten = 0
    s.total = 0
    s.dots = []
  }

  for (const f of feed.foods) {
    if (s.seen.includes(f.id)) continue
    s.seen = [...s.seen, f.id].slice(-200)
    s.total += 1
    for (let tries = 0; tries < 40; tries++) {
      const p = { x: rand(s, W), y: rand(s, H) }
      if (!occupied(s, p)) {
        s.dots.push({ ...p, id: f.id, tool: f.tool })
        break
      }
    }
  }

  if (s.wasWorking && !feed.working) {
    final = { eaten: s.eaten, total: s.total, score: s.score }
  }
  s.wasWorking = feed.working

  // The snake only moves while Claude works.
  if (!feed.working || !s.alive) return { s, final }

  if (s.next !== OPPOSITE[s.dir]) s.dir = s.next
  const head = s.snake[0]!
  const d = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] }[s.dir]
  const nh = { x: (head.x + d[0]! + W) % W, y: (head.y + d[1]! + H) % H }

  if (s.snake.some(c => c.x === nh.x && c.y === nh.y)) {
    s.alive = false
    return { s, final }
  }

  s.snake.unshift(nh)
  const hit = s.dots.findIndex(p => p.x === nh.x && p.y === nh.y)
  if (hit >= 0) {
    s.dots.splice(hit, 1)
    s.score += 1
    s.eaten += 1
  } else {
    s.snake.pop()
  }
  return { s, final }
}

export const press = (s: S, k: ClientKeyEvent): S | undefined => {
  if (k.key === 'r' && !s.alive) return { ...fresh(s.turn, s.seed), score: s.score, total: s.total, eaten: s.eaten, wasWorking: s.wasWorking }
  const dir = KEYS[k.key]
  return dir ? { ...s, next: dir } : undefined
}

// Palette
const BOARD_A = '#15181e'
const BOARD_B = '#181b22'
const FRAME = '#2a2f3a'
const INK = '#0b0d10'
const MUTED = '#6b7280'
const HEAD_ALIVE = '#86efac'
const HEAD_DEAD = '#f87171'

// Body fades from bright to deep green toward the tail.
const BODY = ['#4ade80', '#3fcf73', '#35bf66', '#2cae5a', '#239e4e', '#1b8e43', '#157f3a']
const bodyColor = (i: number, len: number): string =>
  BODY[Math.min(BODY.length - 1, Math.floor((i / Math.max(1, len - 1)) * (BODY.length - 1)))]!

const EYES: Record<Dir, string> = { up: '\u02D9\u02D9', down: '..', left: ': ', right: ' :' }

type Run = { text: string; color?: string; bg?: string; bold?: boolean }

export default function Game(props: Feed, surface: ClientSurface<S>): RenderElement {
  latest.set(surface, props)
  const { Box, Text } = surface.elements

  let s = surface.state
  if (s === undefined) {
    s = fresh(props.turn)
    const start = s
    surface.every(110, () => {
      const cur = surface.state ?? start
      const { s: n, final } = step(cur, latest.get(surface) ?? props)
      if (final) surface.post({ type: 'final', ...final })
      surface.setState(n)
    })
    surface.onKey(k => {
      const n = press(surface.state ?? start, k)
      if (n) surface.setState(n)
    })
  }

  const line = (key: string, runs: Run[]): RenderElement => {
    const merged: Run[] = []
    for (const r of runs) {
      const last = merged[merged.length - 1]
      if (last && last.color === r.color && last.bg === r.bg && last.bold === r.bold) last.text += r.text
      else merged.push({ ...r })
    }
    return (
      <Text key={key}>
        {merged.map((r, i) => (
          <Text key={`${key}-${i}`} color={r.color} backgroundColor={r.bg} bold={r.bold}>
            {r.text}
          </Text>
        ))}
      </Text>
    )
  }

  // Header: title chip, state chip, numbers.
  const state = !s.alive
    ? { label: ' CRASHED ', bg: HEAD_DEAD }
    : props.working
      ? { label: ' LIVE ', bg: '#22c55e' }
      : props.turn === 0
        ? { label: ' READY ', bg: MUTED }
        : { label: ' DONE ', bg: '#38bdf8' }

  const header = line('h', [
    { text: ' TOOL SNAKE ', color: INK, bg: '#4ade80', bold: true },
    { text: ' ' },
    { text: state.label, color: INK, bg: state.bg, bold: true },
    { text: ' score ', color: MUTED },
    { text: String(s.score), color: '#f9fafb', bold: true },
    { text: '  ate ', color: MUTED },
    { text: `${s.eaten}/${s.total}`, color: '#f9fafb', bold: true },
    { text: ' calls', color: MUTED },
  ])

  // Board with a rounded frame.
  const rows: RenderElement[] = [line('top', [{ text: '\u256D' + '\u2500'.repeat(W * 2) + '\u256E', color: FRAME }])]
  const len = s.snake.length
  for (let y = 0; y < H; y++) {
    const runs: Run[] = [{ text: '\u2502', color: FRAME }]
    for (let x = 0; x < W; x++) {
      const body = s.snake.findIndex(c => c.x === x && c.y === y)
      const dot = body < 0 ? s.dots.find(p => p.x === x && p.y === y) : undefined
      if (body === 0) {
        runs.push({ text: EYES[s.dir], color: INK, bg: s.alive ? HEAD_ALIVE : HEAD_DEAD, bold: true })
      } else if (body > 0) {
        runs.push({ text: '  ', bg: s.alive ? bodyColor(body, len) : '#7f1d1d' })
      } else if (dot) {
        runs.push({ text: letter(dot.tool) + ' ', color: INK, bg: colorOf(dot.tool), bold: true })
      } else {
        runs.push({ text: '  ', bg: (x + y) % 2 === 0 ? BOARD_A : BOARD_B })
      }
    }
    runs.push({ text: '\u2502', color: FRAME })
    rows.push(line(`r${y}`, runs))
  }
  rows.push(line('bot', [{ text: '\u2570' + '\u2500'.repeat(W * 2) + '\u256F', color: FRAME }]))

  // Legend and hint.
  const chip = (t: string, name: string, tool: string): Run[] => [
    { text: ` ${t} `, color: INK, bg: colorOf(tool), bold: true },
    { text: ` ${name} `, color: MUTED },
  ]
  const legend = line('legend', [
    ...chip('B', 'bash', 'Bash'),
    ...chip('E', 'edit', 'Edit'),
    ...chip('R', 'read', 'Read'),
    ...chip('W', 'write', 'Write'),
    ...chip('G', 'grep', 'Grep'),
  ])

  const hint = !s.alive
    ? 'crashed into yourself · press r to restart'
    : props.working
      ? 'click to play · arrows / wasd · esc to type'
      : props.turn === 0
        ? 'send Claude a prompt, food drops as it works'
        : `Claude is done \u2713  you ate ${s.eaten} of its ${s.total} tool calls`

  return (
    <Box flexDirection="column">
      {header}
      {rows}
      {legend}
      <Text color={!s.alive ? HEAD_DEAD : props.working ? MUTED : '#38bdf8'}>{hint}</Text>
    </Box>
  )
}

